public class Source {
    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int [] x = new int[n];
        int [] output = new int[n];

        for(int i=0;i<n;i++) {
            x[i] = in.nextInt();
            }

        int[] prefix = new int[n];
        prefix[0] = 1
        for(int i=0;i<n;i++){
            prefix[i] = prefix[i - 1] * x[i-1];
        }

        int suffix = 1;
        for(int i=n-1; i>=0; i--){
            output[i] = prefix[i] * suffix;
            suffix *= x[i];
        }

        for(int num:output){
            System.out.println(num);
        }

        in.close();
   }
}

